using System.Collections.Generic;
using UnityEngine;

namespace PeaHeads
{
    public enum Sfx
    {
        Pop, Splat, Plant, Unplant, Ready, Collect, Appear, HitMarker, Kill, Hurt, Knockout, Respawn, Tick, TickFinal,
        Go, Page, Click, Win, Lose, Draw, Charge,
    }

    // One-shot sound effects generated by tools/make_audio.py, loaded by name from Audio/Resources/Sfx. A name with
    // numbered variants (pop_0, pop_1, ...) picks one at random. Play* return false when the clip is missing so
    // callers can fall back to their own inspector clip.
    public static class GameAudio
    {
        private const float MinDistance = 3f;
        private const float MaxDistance = 45f;

        private static readonly Dictionary<Sfx, AudioClip[]> Clips = new();

        public static bool Has(Sfx sfx) => Load(sfx).Length > 0;

        // First clip of a sound, for callers that need their own (looping) AudioSource. Null when missing.
        public static AudioClip Clip(Sfx sfx)
        {
            AudioClip[] clips = Load(sfx);
            return clips.Length > 0 ? clips[0] : null;
        }

        // Positional: heard by everyone near the position.
        public static bool PlayAt(Sfx sfx, Vector3 position, float volume = 1f, float pitchJitter = 0.06f) =>
            Spawn(sfx, position, volume, pitchJitter, 1f);

        // Flat 2D: UI and the local player's own feedback.
        public static bool Play(Sfx sfx, float volume = 1f, float pitchJitter = 0f) =>
            Spawn(sfx, Vector3.zero, volume, pitchJitter, 0f);

        private static bool Spawn(Sfx sfx, Vector3 position, float volume, float pitchJitter, float spatialBlend)
        {
            AudioClip[] clips = Load(sfx);
            if (clips.Length == 0) return false;
            AudioClip clip = clips[Random.Range(0, clips.Length)];

            var go = new GameObject($"Sfx {sfx}");
            go.transform.position = position;
            var source = go.AddComponent<AudioSource>();
            source.clip = clip;
            source.volume = volume;
            source.pitch = 1f + Random.Range(-pitchJitter, pitchJitter);
            source.spatialBlend = spatialBlend;
            source.minDistance = MinDistance;
            source.maxDistance = MaxDistance;
            source.rolloffMode = AudioRolloffMode.Linear;
            source.dopplerLevel = 0f;
            source.Play();
            Object.Destroy(go, clip.length / source.pitch + 0.1f);
            return true;
        }

        private static AudioClip[] Load(Sfx sfx)
        {
            if (Clips.TryGetValue(sfx, out AudioClip[] cached)) return cached;
            string name = FileName(sfx);
            var found = new List<AudioClip>();
            var single = Resources.Load<AudioClip>($"Sfx/{name}");
            if (single) found.Add(single);
            for (int i = 0; ; i++)
            {
                var variant = Resources.Load<AudioClip>($"Sfx/{name}_{i}");
                if (!variant) break;
                found.Add(variant);
            }
            return Clips[sfx] = found.ToArray();
        }

        private static string FileName(Sfx sfx) => sfx switch
        {
            Sfx.HitMarker => "hitmarker",
            Sfx.TickFinal => "tick_final",
            _ => sfx.ToString().ToLowerInvariant(),
        };
    }
}
